      </svg>
    ),
    color: '#777BB4'
  },
  {
    name: 'MySQL',
    category: 'Database',
    icon: (
      <svg viewBox="0 0 24 24" className="w-8 h-8" fill="none">
        <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2z" fill="#4479A1"/>
        <text x="12" y="15" textAnchor="middle" fill="white" fontSize="6" fontWeight="bold">SQL</text>
      </svg>
    ),
    color: '#4479A1'
  },
  {
    name: 'Node.js',
    category: 'Backend',
    icon: (
      <svg viewBox="0 0 24 24" className="w-8 h-8" fill="#339933">
        <path d="M12 2L3 7v10l9 5 9-5V7l-9-5zm0 2.5L18.5 8 12 11.5 5.5 8 12 4.5zM5 9.5l6 3.5v6.5l-6-3.5V9.5zm14 0v6.5l-6 3.5v-6.5l6-3.5z"/>
      </svg>
    ),
    color: '#339933'
  },
  {
    name: 'Git',
    category: 'Tools',
    icon: (
      <svg viewBox="0 0 24 24" className="w-8 h-8" fill="#F05032">
        <path d="M23.546 10.93L13.067.452c-.604-.603-1.582-.603-2.188 0L8.708 2.627l2.76 2.76c.645-.215 1.379-.09 1.888.417.518.515.658 1.263.438 1.912l2.652 2.66c.645-.223 1.387-.09 1.9.412.72.72.72 1.884 0 2.604-.719.72-1.88.72-2.6 0-.54-.543-.674-1.342-.404-1.996L12.86 8.955v6.525c.176.086.342.203.488.348.713.72.713 1.883 0 2.6-.719.721-1.889.721-2.609 0-.719-.719-.719-1.88 0-2.599.182-.18.387-.316.605-.402V8.835c-.217-.086-.424-.222-.6-.401-.545-.545-.678-1.342-.404-1.996L7.636 3.73.451 10.92c-.603.605-.603 1.584 0 2.189l10.48 10.477c.604.604 1.582.604 2.188 0l10.43-10.43c.605-.603.605-1.582 0-2.187"/>
      </svg>
    ),
    color: '#F05032'
  },
  {
    name: 'Python',
    category: 'Backend',
    icon: (
      <svg viewBox="0 0 24 24" className="w-8 h-8" fill="none">
        <path d="M12 0C5.372 0 0 5.373 0 12c0 6.628 5.372 12 12 12 6.627 0 12-5.372 12-12 0-6.627-5.373-12-12-12z" fill="#3776AB"/>
        <path d="M12.07 2.5c-3.54 0-6.62 1.58-6.62 4.12v2.74c0 1.53 1.26 2.68 2.95 2.68h2.68v1.4c0 .78-.63 1.41-1.4 1.41H5.45v1.89h3.77c2.33 0 4.22-1.9 4.22-4.23V9.36c0-2.32-1.9-4.22-4.23-4.22h-1.4V4.62c0-.97.82-1.4 1.4-1.4h6.73c.59 0 1.41.43 1.41 1.4v2.2h2.68v-2.2c0-2.54-3.08-4.12-6.61-4.12z" fill="#FFD43B"/>
        <path d="M12.07 21.5c3.54 0 6.62-1.58 6.62-4.12v-2.74c0-1.53-1.26-2.68-2.95-2.68h-2.68v-1.4c0-.78.63-1.41 1.4-1.41h4.25v-1.89h-3.77c-2.33 0-4.22 1.9-4.22 4.23v2.06c0 2.32 1.9 4.22 4.23 4.22h1.4v2.52c0 .97-.82 1.4-1.4 1.4H7.62c-.59 0-1.41-.43-1.41-1.4v-2.2H3.54v2.2c0 2.54 3.08 4.12 6.61 4.12z" fill="#FFD43B"/>
      </svg>
    ),
    color: '#3776AB'
  },
  {
    name: 'Laravel',
    category: 'Backend',
    icon: (
      <svg viewBox="0 0 24 24" className="w-8 h-8" fill="none">
        <path d="M12 2L2 7v10l10 5 10-5V7L12 2z" fill="#FF2D20"/>
        <path d="M7 9l5 2.5L17 9v6l-5 2.5L7 15V9z" fill="white"/>
      </svg>
    ),
    color: '#FF2D20'
  },
  {
    name: 'C++',
    category: 'Language',
    icon: (
      <svg viewBox="0 0 24 24" className="w-8 h-8" fill="none">
        <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2z" fill="#00599C"/>
        <text x="12" y="16" textAnchor="middle" fill="white" fontSize="9" fontWeight="bold">C++</text>
      </svg>
    ),
    color: '#00599C'
  },
  {
    name: 'Java',
    category: 'Language',
    icon: (
      <svg viewBox="0 0 24 24" className="w-8 h-8" fill="none">
        <path d="M8.85 18.3s-.85.5.6.67c1.76.2 2.66.17 4.6-.19 0 0 .51.32 1.22.6-4.36 1.87-9.86-.11-6.42-1.08zm-.54-2.45s-.95.7.5.85c1.87.19 3.36.2 5.92-.28 0 0 .35.36.9.55-5.23 1.53-11.08.1-7.32-1.12z" fill="#5382A1"/>
        <path d="M13.86 10.6c1.06 1.22-.28 2.32-.28 2.32s2.69-1.39 1.45-3.14c-1.18-1.65-2.09-2.47 2.82-5.3 0 0-7.71 1.92-4 6.12z" fill="#F8981D"/>
        <path d="M19.3 19.64s.63.52-.69.92c-2.52.76-10.43 1-12.64.03-.79-.35.69-.82 1.16-.92.48-.1.76-.08.76-.08-.87-.61-5.6 1.2-2.4 1.72 8.68 1.41 15.83-.64 11.81-1.67z" fill="#5382A1"/>
      </svg>
    ),
    color: '#F8981D'
  },
  {
    name: 'Electron.js',
    category: 'Framework',
    icon: (
      <svg viewBox="0 0 24 24" className="w-8 h-8" fill="none">
        <circle cx="12" cy="12" r="10" fill="#47848F"/>
        <ellipse cx="12" cy="12" rx="4" ry="8" fill="none" stroke="#9FEAF9" strokeWidth="1.5"/>
        <ellipse cx="12" cy="12" rx="8" ry="4" fill="none" stroke="#9FEAF9" strokeWidth="1.5"/>
        <circle cx="12" cy="12" r="2" fill="#9FEAF9"/>
      </svg>
    ),
    color: '#47848F'
  }
];

const Technologies = () => {
  const sectionRef = useRef(null);
  const [skills, setSkills] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(`${API_URL}/skills.php`)
      .then(res => res.json())
      .then(data => {
        setSkills(data);
        setLoading(false);
      })
      .catch(err => {
        console.error('Error fetching skills:', err);
        setLoading(false);
      });
  }, []);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -50px 0px' }
    );

    const reveals = sectionRef.current?.querySelectorAll('.reveal');
    reveals?.forEach((el) => observer.observe(el));

    return () => observer.disconnect();
  }, []);

  return (
    <section id="technologies" ref={sectionRef} className="py-24 bg-[#0a1628] relative overflow-hidden">
      {/* Background elements */}
      <div className="absolute top-0 right-0 w-96 h-96 bg-blue-500/5 rounded-full blur-3xl"></div>
      <div className="absolute bottom-0 left-0 w-80 h-80 bg-purple-500/5 rounded-full blur-3xl"></div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section Header */}
        <div className="text-center mb-16 reveal">
          <span className="inline-block px-4 py-2 rounded-full bg-blue-500/10 text-blue-400 text-sm font-medium mb-4">
            Tech Stack
          </span>
          <h2 className="text-4xl sm:text-5xl font-bold text-white mb-6">
            Technologies <span className="gradient-text">We Use</span>
          </h2>
          <p className="text-gray-400 max-w-2xl mx-auto text-lg">
            We leverage modern technologies and tools to build scalable, 
            efficient, and maintainable web solutions.
          </p>
        </div>

        {/* Tech Grid */}
        <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-4 mb-16">
          {technologies.map((tech, index) => (
            <div
              key={tech.name}
              className="reveal group"
              style={{ transitionDelay: `${index * 50}ms` }}
            >
              <div className="card-minimal rounded-xl p-4 text-center relative overflow-hidden">
                {/* Glow effect */}
                <div 
                  className="absolute inset-0 opacity-0 group-hover:opacity-20 transition-opacity duration-300 rounded-2xl"
                  style={{ background: `radial-gradient(circle at center, ${tech.color}, transparent)` }}
                ></div>

                <div className="relative z-10">
                  <div className="w-12 h-12 mx-auto mb-3 flex items-center justify-center text-gray-300 group-hover:scale-110 transition-transform duration-300" style={{ color: tech.color }}>
                    {tech.icon}
                  </div>
                  <h3 className="text-base font-semibold text-white mb-1">{tech.name}</h3>
                  <p className="text-xs text-gray-400">{tech.category}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Additional Info */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 reveal">
          <div className="card-minimal rounded-xl p-6 text-center">
            <div className="text-4xl font-bold gradient-text mb-2">Modern</div>
            <p className="text-gray-400 text-sm">Latest frameworks and libraries</p>
          </div>
          <div className="card-minimal rounded-xl p-6 text-center">
            <div className="text-4xl font-bold gradient-text mb-2">Scalable</div>
            <p className="text-gray-400 text-sm">Built for growth and performance</p>
          </div>
          <div className="card-minimal rounded-xl p-6 text-center">
            <div className="text-4xl font-bold gradient-text mb-2">Secure</div>
            <p className="text-gray-400 text-sm">Best practices in security</p>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Technologies;
